// Des: Tests for ru-spen-guar and ru-kill-swit: free, paid, cap, kill
// Flo: temp db > record spend > check decisions around free quota, cap and kill
// I/O: numbers > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const spen = @import("ru-spen-guar.zig"); const kill = @import("ru-kill-swit.zig"); const inde = @import("st-page-inde.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
const Rigg = struct { tmpz: std.testing.TmpDir, dirz: []u8, dbzz: @import("st-stor-sqli.zig").Dbzz, pub fn upzz(self: *Rigg) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); } pub fn down(self: *Rigg) void { self.dbzz.close(); allo.free(self.dirz); self.tmpz.cleanup(); } };
const NOWZ: i64 = 1790000000000;
test "month number from epoch ms" { try std.testing.expectEqual(@as(i64, 197001), spen.montOfzz(0)); try std.testing.expectEqual(@as(i64, 202609), spen.montOfzz(1790000000000)); try std.testing.expectEqual(@as(i64, 197001), spen.montOfzz(-5)); }
test "default config is free-only: zero free credits means nothing passes" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const decz = try spen.spenChek(&rig3.dbzz, .{}, .zenr, 1, NOWZ, true); try std.testing.expect(!decz.okay); }
test "free credits cover cost until used up, then a paid call needs go and a cap" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); var conf: cfgz.Conf = .{}; conf.vend_free_cred.zenr = 10; const one2 = try spen.spenChek(&rig3.dbzz, conf, .zenr, 5, NOWZ, false); try std.testing.expect(one2.okay and !one2.paid); try spen.spenRecz(&rig3.dbzz, .zenr, 5, 0, NOWZ); try spen.spenRecz(&rig3.dbzz, .zenr, 5, 0, NOWZ); const two2 = try spen.spenChek(&rig3.dbzz, conf, .zenr, 1, NOWZ, false); try std.testing.expect(!two2.okay); const triz = try spen.spenChek(&rig3.dbzz, conf, .zenr, 1, NOWZ, true); try std.testing.expect(!triz.okay); try std.testing.expectEqualStrings("over capz_usdz_mont", triz.why2); conf.capz_usdz_mont = 0.01; const fouz = try spen.spenChek(&rig3.dbzz, conf, .zenr, 5, NOWZ, true); try std.testing.expect(fouz.okay and fouz.paid); try std.testing.expectEqual(@as(u64, 5000), fouz.micr); const fivz = try spen.spenChek(&rig3.dbzz, conf, .zenr, 11, NOWZ, true); try std.testing.expect(!fivz.okay); }
test "spend adds up across vendors and resets next month" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try spen.spenRecz(&rig3.dbzz, .zenr, 5, 5000, NOWZ); try spen.spenRecz(&rig3.dbzz, .deco, 2, 2000, NOWZ); try std.testing.expectEqual(@as(i64, 7000), try spen.spenTota(&rig3.dbzz, NOWZ)); try std.testing.expectEqual(@as(i64, 5), try spen.spenUsed(&rig3.dbzz, .zenr, NOWZ)); try std.testing.expectEqual(@as(i64, 0), try spen.spenTota(&rig3.dbzz, NOWZ + 40 * 86400000)); }
test "kill switch halts everything, even free spend; survives reopen" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); var conf: cfgz.Conf = .{}; conf.vend_free_cred.deco = 100; try std.testing.expect((try spen.spenChek(&rig3.dbzz, conf, .deco, 1, NOWZ, false)).okay); try kill.killSetz(&rig3.dbzz, true); const decz = try spen.spenChek(&rig3.dbzz, conf, .deco, 1, NOWZ, true); try std.testing.expect(!decz.okay); try std.testing.expectEqualStrings("kill switch on", decz.why2); try kill.killSetz(&rig3.dbzz, false); try std.testing.expect((try spen.spenChek(&rig3.dbzz, conf, .deco, 1, NOWZ, false)).okay); }
